[Console]::OutputEncoding = [System.Text.Encoding]::UTF8; $ProgressPreference = 'SilentlyContinue'

# Helper function to handle null values and escape special characters
function HandleString($value) {
    if ($null -eq $value) { 
        return "-" 
    } else { 
        return $value -replace '"', '\"'  # Escape double quotes
    }
}

try {
    $ouList = @()
    $domain = HandleString((Get-ADDomainController).Forest)
    $properties = @("Name", "ManagedBy", "Created", "Modified", "DistinguishedName", "ObjectGUID", "isCriticalSystemObject")

    $linkedOu = @{}
    foreach ($gpi in Get-ADOrganizationalUnit -Filter * | Get-GPInheritance) {
        if ($null -eq $gpi) {
            continue
        }
        $linkedGPO = @()
        foreach ($lgpo in $gpi.GpoLinks) {
            $linkedGPO += @{
                "name" = HandleString($lgpo.DisplayName)
                "enabled" = $lgpo.Enabled
                "enforced" = $lgpo.Enforced
            }
        }
        try {
            foreach ($lgpo in $gpi.InheritedGpoLinks) {
                $linkedGPO += @{
                    "name" = HandleString($lgpo.DisplayName)
                    "enabled" = $lgpo.Enabled
                    "enforced" = $lgpo.Enforced
                }
            }
        }
        catch {
        }
        $linkedOu[$gpi.name] = $linkedGPO
    }

    foreach ($o in Get-ADOrganizationalUnit -Filter "*" -Properties $properties) {
        if ($null -eq $o) {
            continue
        }
        if ($o.DistinguishedName -notlike '*OU=*') {
            continue
        }
        $empty = $false
        if (-not (Get-ADObject -SearchBase $o -SearchScope OneLevel -Filter *)) {
            $empty = $true
        }

        $ouIsCritical = if ($null -ne $o.isCriticalSystemObject) { $o.isCriticalSystemObject } else { $false }

        $linkedComputers = @()
        foreach ($computer in Get-ADComputer -SearchBase $o.DistinguishedName -Filter *) {
            $linkedComputers += HandleString($computer.Name)
        }

        $linkedGroups = @()
        foreach ($group in Get-ADGroup -SearchBase $o.DistinguishedName -Filter *) {
            $linkedGroups += HandleString($group.Name)
        }

        $linkedUsers = @()
        foreach ($user in Get-ADUser -SearchBase $o.DistinguishedName -Filter *) {
            $linkedUsers += HandleString($user.Name)
        }

        $ouList += @{
            "domain" = $domain
            "ou" = HandleString($o.Name)
            "name" = HandleString($o.Name)
            "managedBy" = HandleString($o.ManagedBy)
            "modifiedwhen" = $o.Modified.ToString("dd-MM-yyyy HH:mm:ss")
            "createdwhen" = $o.Created.ToString("dd-MM-yyyy HH:mm:ss")
            "distinguishedName" = HandleString($o.DistinguishedName)
            "objectguid" = HandleString($o.ObjectGUID)
            "empty" = $empty
            "gplink" = $linkedOu[$o.Name]
            "iscriticalsystemobject" = $ouIsCritical
            "linkedComputers" = $linkedComputers
            "linkedGroups" = $linkedGroups
            "linkedUsers" = $linkedUsers
        }
    }

    $jsonResult = $ouList | ConvertTo-Json -Depth 5

    # Define primary and fallback paths
    $primaryPath = "C:\Program Files (x86)\CyberCNSAgent\agent_temp\ad_ous.json"
    $fallbackPath = "C:\Windows\cybercnsagent\agent_temp\ad_ous.json"

    # Get directory paths
    $primaryDir = Split-Path $primaryPath -Parent
    $fallbackDir = Split-Path $fallbackPath -Parent

    # Determine final path
    if (Test-Path $primaryDir) {
        $finalPath = $primaryPath
    } else {
        # Ensure fallback directory exists
        if (-not (Test-Path $fallbackDir)) {
            New-Item -Path $fallbackDir -ItemType Directory -Force | Out-Null
        }
        $finalPath = $fallbackPath
    }

    # Ensure directory exists before writing
    $finalDir = Split-Path $finalPath -Parent
    if (-not (Test-Path $finalDir)) {
        New-Item -Path $finalDir -ItemType Directory -Force | Out-Null
    }

    # Save JSON result
    $jsonResult | Out-File -FilePath $finalPath -Encoding UTF8

    Write-Output $jsonResult
}
catch {
    ConvertTo-Json -Depth 5 -Compress @{
        status = $false
        msg = $( $_.Exception.Message )
        stackTrace = $_ | Out-String
    }
}
